-- V1__init.sql (đã sửa từ bản export gốc)
-- Đã sửa: bỏ index trùng PK/UNIQUE, sửa index biểu thức, đổi user_id -> customer_id,
-- khôi phục WHERE/DESC của các index bị mất khi export.

CREATE TABLE "admins" (
                          "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "admins_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                          "firebase_uid" varchar(255) NOT NULL CONSTRAINT "uk_admins_firebase_uid" UNIQUE,
                          "email" varchar(255) NOT NULL CONSTRAINT "uk_admins_email" UNIQUE,
                          "full_name" varchar(255) NOT NULL,
                          "status" varchar(20) DEFAULT 'ACTIVE' NOT NULL,
                          "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                          "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
                          CONSTRAINT "ck_admins_status" CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INACTIVE'::character varying, 'SUSPENDED'::character varying])::text[])))
);
CREATE TABLE "chat_messages" (
                                 "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "chat_messages_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                                 "conversation_id" bigint NOT NULL,
                                 "sender_role" varchar(10) NOT NULL,
                                 "sender_customer_id" bigint,
                                 "sender_driver_id" bigint,
                                 "message_type" varchar(20) DEFAULT 'TEXT' NOT NULL,
                                 "content" text DEFAULT '' NOT NULL,
                                 "attachment_url" text,
                                 "cloudinary_public_id" text,
                                 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                                 "read_at" timestamp with time zone,
                                 CONSTRAINT "ck_chat_messages_content" CHECK (((length(btrim(content)) > 0) OR (attachment_url IS NOT NULL))),
                                 CONSTRAINT "ck_chat_messages_sender" CHECK (((((sender_role)::text = 'CUSTOMER'::text) AND (sender_customer_id IS NOT NULL) AND (sender_driver_id IS NULL)) OR (((sender_role)::text = 'DRIVER'::text) AND (sender_driver_id IS NOT NULL) AND (sender_customer_id IS NULL)) OR (((sender_role)::text = 'SYSTEM'::text) AND (sender_customer_id IS NULL) AND (sender_driver_id IS NULL))))
);
CREATE TABLE "conversations" (
                                 "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "conversations_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                                 "ride_id" bigint NOT NULL CONSTRAINT "conversations_ride_id_key" UNIQUE,
                                 "customer_id" bigint NOT NULL,
                                 "driver_id" bigint NOT NULL,
                                 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                                 "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE "device_tokens" (
                                 "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "device_tokens_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                                 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                                 "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
                                 "fcm_token" varchar(255) NOT NULL CONSTRAINT "uk_device_token" UNIQUE,
                                 "installation_id" varchar(36) NOT NULL CONSTRAINT "uk_device_installation" UNIQUE,
                                 "last_seen_at" timestamp with time zone DEFAULT now() NOT NULL,
                                 "owner_id" bigint NOT NULL,
                                 "platform" varchar(20) NOT NULL,
                                 "role" varchar(20) NOT NULL,
                                 "is_active" boolean DEFAULT true NOT NULL,
                                 "revoked_at" timestamp with time zone,
                                 CONSTRAINT "device_tokens_role_check" CHECK (((role)::text = ANY ((ARRAY['DRIVER'::character varying, 'CUSTOMER'::character varying])::text[])))
);
CREATE TABLE "driver_documents" (
                                    "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "driver_documents_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                                    "driver_id" bigint NOT NULL,
                                    "document_type" varchar(50) NOT NULL,
                                    "document_number" varchar(100),
                                    "secure_url" text NOT NULL,
                                    "cloudinary_public_id" text NOT NULL,
                                    "resource_type" varchar(20) DEFAULT 'image' NOT NULL,
                                    "verification_status" varchar(20) DEFAULT 'PENDING' NOT NULL,
                                    "rejection_reason" text,
                                    "expires_at" date,
                                    "is_current" boolean DEFAULT true NOT NULL,
                                    "reviewed_at" timestamp with time zone,
                                    "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                                    "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
                                    "reviewed_by_admin_id" bigint,
                                    CONSTRAINT "ck_driver_documents_resource_type" CHECK (((resource_type)::text = ANY ((ARRAY['image'::character varying, 'raw'::character varying, 'video'::character varying, 'auto'::character varying])::text[]))),
	CONSTRAINT "ck_driver_documents_status" CHECK (((verification_status)::text = ANY ((ARRAY['PENDING'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying])::text[])))
);
CREATE TABLE "drivers" (
                           "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "drivers_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                           "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                           "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
                           "avatar_url" text,
                           "average_rating" double precision,
                           "bank_account_number" varchar(255),
                           "email" varchar(255),
                           "firebase_uid" varchar(255) NOT NULL CONSTRAINT "uko72wo4d8bch6sb6il2vb9x5e0" UNIQUE,
                           "full_name" varchar(255),
                           "last_location_update" timestamp,
                           "license_class" varchar(10),
                           "license_number" varchar(255),
                           "income_balance" bigint DEFAULT 0,
                           "phone_number" varchar(255) NOT NULL CONSTRAINT "uk_drivers_phone_number" UNIQUE,
                           "status" varchar(255) DEFAULT 'OFFLINE' NOT NULL,
                           "credit_balance" bigint DEFAULT 0,
                           "years_of_experience" integer,
                           "acceptance_rate" double precision,
                           "background_check_status" varchar(255),
                           "cancel_rate_30d" double precision,
                           "completion_rate" double precision,
                           "is_flagged" boolean DEFAULT false,
                           "license_expiry_date" date,
                           "license_verified" boolean DEFAULT false,
                           "total_trips" integer DEFAULT 0,
                           "online_status" varchar(255),
                           "pending_payout" bigint,
                           "wallet_balance" bigint,
                           "avatar_public_id" text,
                           "verification_status" varchar(20) DEFAULT 'PENDING',
                           CONSTRAINT "ck_drivers_credit_balance_nonnegative" CHECK (((credit_balance IS NULL) OR (credit_balance >= 0))),
                           CONSTRAINT "ck_drivers_income_balance_nonnegative" CHECK (((income_balance IS NULL) OR (income_balance >= 0))),
                           CONSTRAINT "ck_drivers_pending_payout_nonnegative" CHECK (((pending_payout IS NULL) OR ((pending_payout)::numeric >= (0)::numeric))),
	CONSTRAINT "ck_drivers_verification_status" CHECK (((verification_status IS NULL) OR ((verification_status)::text = ANY ((ARRAY['PENDING'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying, 'SUSPENDED'::character varying])::text[])))),
	CONSTRAINT "ck_drivers_wallet_balance_nonnegative" CHECK (((wallet_balance IS NULL) OR ((wallet_balance)::numeric >= (0)::numeric))),
	CONSTRAINT "drivers_average_rating_check" CHECK (((average_rating IS NULL) OR ((average_rating >= (0)::double precision) AND (average_rating <= (5)::double precision)))),
	CONSTRAINT "drivers_status_check" CHECK (((status)::text = ANY ((ARRAY['OFFLINE'::character varying, 'ONLINE'::character varying, 'BUSY'::character varying])::text[])))
);
CREATE TABLE "handover_photos" (
                                   "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "handover_photos_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                                   "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                                   "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
                                   "angle" varchar(16) NOT NULL,
                                   "file_url" text NOT NULL,
                                   "report_id" bigint NOT NULL,
                                   "cloudinary_public_id" text,
                                   CONSTRAINT "handover_photos_angle_check" CHECK (((angle)::text = ANY ((ARRAY['FRONT'::character varying, 'BACK'::character varying, 'LEFT'::character varying, 'RIGHT'::character varying, 'DASHBOARD'::character varying])::text[])))
);
CREATE TABLE "notifications" (
                                 "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "notifications_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                                 "recipient_customer_id" bigint,
                                 "recipient_driver_id" bigint,
                                 "ride_id" bigint,
                                 "notification_type" varchar(60) NOT NULL,
                                 "title" varchar(255) NOT NULL,
                                 "body" text NOT NULL,
                                 "data" jsonb DEFAULT '{}' NOT NULL,
                                 "delivery_status" varchar(20) DEFAULT 'PENDING' NOT NULL,
                                 "provider_message_id" varchar(255),
                                 "delivery_error" text,
                                 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                                 "sent_at" timestamp with time zone,
                                 "read_at" timestamp with time zone,
                                 CONSTRAINT "ck_notifications_delivery_status" CHECK (((delivery_status)::text = ANY ((ARRAY['PENDING'::character varying, 'SENT'::character varying, 'FAILED'::character varying, 'SKIPPED'::character varying])::text[]))),
	CONSTRAINT "ck_notifications_one_recipient" CHECK (((recipient_customer_id IS NOT NULL) <> (recipient_driver_id IS NOT NULL)))
);
CREATE TABLE "payment_transactions" (
                                        "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "payment_transactions_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                                        "amount" bigint NOT NULL,
                                        "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                                        "payment_id" bigint NOT NULL,
                                        "provider" varchar(255) NOT NULL,
                                        "provider_transaction_id" varchar(255),
                                        "raw_response" text,
                                        "status" varchar(255) NOT NULL,
                                        CONSTRAINT "payment_transactions_amount_check" CHECK ((amount >= 0)),
                                        CONSTRAINT "payment_transactions_status_check" CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'PAID'::character varying, 'FAILED'::character varying, 'REFUNDED'::character varying])::text[])))
);
CREATE TABLE "payments" (
                            "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "payments_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                            "amount" bigint NOT NULL,
                            "ride_id" bigint NOT NULL CONSTRAINT "uk_payments_ride" UNIQUE,
                            "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                            "customer_id" bigint NOT NULL,
                            "driver_id" bigint,
                            "method" varchar(255) NOT NULL,
                            "paid_at" timestamp with time zone,
                            "status" varchar(255) NOT NULL,
                            "updated_at" timestamp with time zone DEFAULT now(),
                            CONSTRAINT "payments_amount_check" CHECK ((amount >= 0)),
                            CONSTRAINT "payments_method_check" CHECK (((method)::text = ANY ((ARRAY['CASH'::character varying, 'WALLET'::character varying, 'VNPAY'::character varying, 'MOMO'::character varying])::text[]))),
	CONSTRAINT "payments_status_check" CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'PAID'::character varying, 'FAILED'::character varying, 'REFUNDED'::character varying])::text[])))
);
CREATE TABLE "pricing_rules" (
                                 "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "pricing_rules_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                                 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                                 "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
                                 "active" boolean DEFAULT true NOT NULL,
                                 "base_fare" bigint NOT NULL,
                                 "min_fare" bigint NOT NULL,
                                 "night_end" time,
                                 "night_start" time,
                                 "night_surcharge_percent" integer DEFAULT 0 NOT NULL,
                                 "per_km" bigint NOT NULL,
                                 "per_minute_waiting" bigint NOT NULL,
                                 "return_fee_for_driver" bigint NOT NULL,
                                 "vehicle_type" varchar(30),
                                 CONSTRAINT "pricing_rules_amount_check" CHECK (((base_fare >= 0) AND (per_km >= 0) AND (per_minute_waiting >= 0) AND (min_fare >= 0) AND (return_fee_for_driver >= 0))),
                                 CONSTRAINT "pricing_rules_night_percent_check" CHECK (((night_surcharge_percent >= 0) AND (night_surcharge_percent <= 100))),
                                 CONSTRAINT "pricing_rules_vehicle_type_check" CHECK (((vehicle_type IS NULL) OR ((vehicle_type)::text = ANY ((ARRAY['CAR'::character varying, 'MOTORCYCLE'::character varying])::text[]))))
);
CREATE TABLE "ratings" (
                           "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "ratings_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                           "ride_id" bigint NOT NULL,
                           "comment" text,
                           "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                           "direction" varchar(255) NOT NULL,
                           "ratee_id" bigint NOT NULL,
                           "rater_id" bigint NOT NULL,
                           "stars" integer NOT NULL,
                           "tags" varchar(255),
                           CONSTRAINT "uk_ratings_ride_direction" UNIQUE("ride_id","direction"),
                           CONSTRAINT "ratings_stars_check" CHECK (((stars >= 1) AND (stars <= 5)))
);
CREATE TABLE "ride_status_histories" (
                                         "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "ride_status_histories_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                                         "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                                         "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
                                         "actor_id" bigint,
                                         "from_status" varchar(32),
                                         "note" text,
                                         "to_status" varchar(32) NOT NULL,
                                         "ride_id" bigint NOT NULL,
                                         "actor_role" varchar(20),
                                         CONSTRAINT "ride_status_histories_actor_role_check" CHECK (((actor_role IS NULL) OR ((actor_role)::text = ANY ((ARRAY['CUSTOMER'::character varying, 'DRIVER'::character varying, 'SYSTEM'::character varying])::text[])))),
	CONSTRAINT "ride_status_histories_from_status_check" CHECK (((from_status)::text = ANY ((ARRAY['PENDING'::character varying, 'SEARCHING'::character varying, 'DRIVER_ASSIGNED'::character varying, 'DRIVER_ARRIVING'::character varying, 'DRIVER_ARRIVED'::character varying, 'VEHICLE_HANDOVER'::character varying, 'IN_PROGRESS'::character varying, 'ARRIVED_DESTINATION'::character varying, 'VEHICLE_RETURNED'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'NO_DRIVER_FOUND'::character varying, 'EXPIRED'::character varying])::text[]))),
	CONSTRAINT "ride_status_histories_to_status_check" CHECK (((to_status)::text = ANY ((ARRAY['PENDING'::character varying, 'SEARCHING'::character varying, 'DRIVER_ASSIGNED'::character varying, 'DRIVER_ARRIVING'::character varying, 'DRIVER_ARRIVED'::character varying, 'VEHICLE_HANDOVER'::character varying, 'IN_PROGRESS'::character varying, 'ARRIVED_DESTINATION'::character varying, 'VEHICLE_RETURNED'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'NO_DRIVER_FOUND'::character varying, 'EXPIRED'::character varying])::text[])))
);
CREATE TABLE "rides" (
                         "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "rides_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                         "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                         "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
                         "accepted_at" timestamp with time zone,
                         "cancel_reason" varchar(255),
                         "cancelled_at" timestamp with time zone,
                         "completed_at" timestamp with time zone,
                         "customer_id" bigint NOT NULL,
                         "discount_amount" bigint DEFAULT 0,
                         "distance_km" double precision,
                         "driver_id" bigint,
                         "dropoff_address" varchar(255),
                         "dropoff_lat" double precision,
                         "dropoff_lng" double precision,
                         "fare_estimate" bigint NOT NULL,
                         "final_fare" bigint,
                         "license_plate" varchar(20),
                         "note" varchar(500),
                         "payment_method" varchar(30) NOT NULL,
                         "pickup_address" varchar(255),
                         "pickup_lat" double precision,
                         "pickup_lng" double precision,
                         "scheduled_at" timestamp with time zone,
                         "started_at" timestamp with time zone,
                         "status" varchar(30) DEFAULT 'PENDING' NOT NULL,
                         "transmission" varchar(30) NOT NULL,
                         "vehicle_type" varchar(30) NOT NULL,
                         "version" bigint DEFAULT 0 NOT NULL,
                         "cancelled_by" bigint,
                         "type" varchar(16) NOT NULL,
                         "vehicle_id" bigint NOT NULL,
                         "cancelled_by_role" varchar(20),
                         CONSTRAINT "uq_rides_id_customer" UNIQUE("id","customer_id"),
                         CONSTRAINT "uq_rides_id_driver" UNIQUE("id","driver_id"),
                         CONSTRAINT "ck_rides_dropoff_lat_range" CHECK (((dropoff_lat IS NULL) OR ((dropoff_lat >= ('-90'::integer)::double precision) AND (dropoff_lat <= (90)::double precision)))),
                         CONSTRAINT "ck_rides_dropoff_lng_range" CHECK (((dropoff_lng IS NULL) OR ((dropoff_lng >= ('-180'::integer)::double precision) AND (dropoff_lng <= (180)::double precision)))),
                         CONSTRAINT "ck_rides_pickup_lat_range" CHECK (((pickup_lat IS NULL) OR ((pickup_lat >= ('-90'::integer)::double precision) AND (pickup_lat <= (90)::double precision)))),
                         CONSTRAINT "ck_rides_pickup_lng_range" CHECK (((pickup_lng IS NULL) OR ((pickup_lng >= ('-180'::integer)::double precision) AND (pickup_lng <= (180)::double precision)))),
                         CONSTRAINT "rides_amount_check" CHECK (((fare_estimate >= 0) AND ((discount_amount IS NULL) OR (discount_amount >= 0)) AND ((final_fare IS NULL) OR (final_fare >= 0)))),
                         CONSTRAINT "rides_cancelled_by_role_check" CHECK (((cancelled_by_role IS NULL) OR ((cancelled_by_role)::text = ANY ((ARRAY['CUSTOMER'::character varying, 'DRIVER'::character varying, 'SYSTEM'::character varying])::text[])))),
	CONSTRAINT "rides_distance_check" CHECK (((distance_km IS NULL) OR (distance_km >= (0)::double precision))),
	CONSTRAINT "rides_payment_method_check" CHECK (((payment_method)::text = ANY ((ARRAY['CASH'::character varying, 'WALLET'::character varying, 'VNPAY'::character varying, 'MOMO'::character varying])::text[]))),
	CONSTRAINT "rides_scheduled_at_check" CHECK ((((type)::text <> 'SCHEDULED'::text) OR (scheduled_at IS NOT NULL))),
	CONSTRAINT "rides_status_check" CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'SEARCHING'::character varying, 'DRIVER_ASSIGNED'::character varying, 'DRIVER_ARRIVING'::character varying, 'DRIVER_ARRIVED'::character varying, 'VEHICLE_HANDOVER'::character varying, 'IN_PROGRESS'::character varying, 'ARRIVED_DESTINATION'::character varying, 'VEHICLE_RETURNED'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'NO_DRIVER_FOUND'::character varying, 'EXPIRED'::character varying])::text[]))),
	CONSTRAINT "rides_transmission_check" CHECK (((transmission)::text = ANY ((ARRAY['MANUAL'::character varying, 'AUTO'::character varying])::text[]))),
	CONSTRAINT "rides_type_check" CHECK (((type)::text = ANY ((ARRAY['INSTANT'::character varying, 'SCHEDULED'::character varying])::text[]))),
	CONSTRAINT "rides_vehicle_type_check" CHECK (((vehicle_type)::text = ANY ((ARRAY['CAR'::character varying, 'MOTORCYCLE'::character varying])::text[])))
);
CREATE TABLE "customers" (
                             "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "customers_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                             "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                             "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
                             "avatar_url" text,
                             "average_rating" double precision,
                             "default_payment_method" varchar(255),
                             "email" varchar(255),
                             "firebase_uid" varchar(255) NOT NULL CONSTRAINT "uk4yiq7pdiwjw8inhg1xy83nabx" UNIQUE,
                             "full_name" varchar(255),
                             "phone_number" varchar(255) CONSTRAINT "uk_customers_phone_number" UNIQUE,
                             "status" varchar(255) DEFAULT 'ACTIVE' NOT NULL,
                             "wallet_balance" bigint DEFAULT 0,
                             "cancel_rate_30d" double precision DEFAULT 0,
                             "date_of_birth" date,
                             "gender" varchar(255),
                             "is_flagged" boolean DEFAULT false,
                             "last_login_at" timestamp,
                             "total_cancelled" integer DEFAULT 0,
                             "total_trips" integer DEFAULT 0,
                             "avatar_public_id" text,
                             CONSTRAINT "customers_average_rating_check" CHECK (((average_rating IS NULL) OR ((average_rating >= (0)::double precision) AND (average_rating <= (5)::double precision)))),
                             CONSTRAINT "customers_default_payment_method_check" CHECK (((default_payment_method IS NULL) OR ((default_payment_method)::text = ANY ((ARRAY['CASH'::character varying, 'WALLET'::character varying, 'VNPAY'::character varying, 'MOMO'::character varying])::text[])))),
	CONSTRAINT "customers_status_check" CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INACTIVE'::character varying, 'BANNED'::character varying])::text[]))),
	CONSTRAINT "customers_wallet_balance_check" CHECK (((wallet_balance IS NULL) OR ((wallet_balance)::numeric >= (0)::numeric)))
);
CREATE TABLE "vehicle_handover_reports" (
                                            "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "vehicle_handover_reports_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                                            "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                                            "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
                                            "confirmed_by_customer" boolean DEFAULT false NOT NULL,
                                            "fuel_level" integer,
                                            "notes" text,
                                            "odometer" bigint NOT NULL,
                                            "phase" varchar(16) NOT NULL,
                                            "ride_id" bigint NOT NULL,
                                            CONSTRAINT "uk_handover_ride_phase" UNIQUE("ride_id","phase"),
                                            CONSTRAINT "vehicle_handover_reports_fuel_level_check" CHECK (((fuel_level IS NULL) OR ((fuel_level >= 0) AND (fuel_level <= 100)))),
                                            CONSTRAINT "vehicle_handover_reports_odometer_check" CHECK ((odometer >= 0)),
                                            CONSTRAINT "vehicle_handover_reports_phase_check" CHECK (((phase)::text = ANY ((ARRAY['PICKUP'::character varying, 'DROPOFF'::character varying])::text[])))
);
CREATE TABLE "vehicle_images" (
                                  "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "vehicle_images_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                                  "vehicle_id" bigint NOT NULL,
                                  "image_type" varchar(30) DEFAULT 'OTHER' NOT NULL,
                                  "secure_url" text NOT NULL,
                                  "cloudinary_public_id" text NOT NULL,
                                  "created_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE "vehicles" (
                            "id" bigserial PRIMARY KEY,
                            "customer_id" bigint NOT NULL,
                            "plate_number" varchar(20) NOT NULL CONSTRAINT "vehicles_plate_number_key" UNIQUE,
                            "brand_model" varchar(100),
                            "transmission_type" varchar(10),
                            "created_at" timestamp with time zone DEFAULT now() NOT NULL,
                            "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
                            "vehicle_type" varchar(30) DEFAULT 'CAR' NOT NULL,
                            CONSTRAINT "uq_vehicles_id_user" UNIQUE("id","customer_id"),
                            CONSTRAINT "vehicles_transmission_type_check" CHECK (((transmission_type IS NULL) OR ((transmission_type)::text = ANY ((ARRAY['MANUAL'::character varying, 'AUTO'::character varying])::text[])))),
	CONSTRAINT "vehicles_vehicle_type_check" CHECK (((vehicle_type)::text = ANY ((ARRAY['CAR'::character varying, 'MOTORCYCLE'::character varying])::text[])))
);
CREATE TABLE "voucher_usages" (
                                  "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "voucher_usages_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                                  "ride_id" bigint,
                                  "used_at" timestamp with time zone DEFAULT now() NOT NULL,
                                  "customer_id" bigint NOT NULL,
                                  "voucher_id" bigint NOT NULL,
                                  CONSTRAINT "ukjv33btd6ra0fvgsldq1pipxjr" UNIQUE("voucher_id","customer_id")
);
CREATE TABLE "vouchers" (
                            "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "vouchers_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
                            "code" varchar(255) NOT NULL CONSTRAINT "uk30ftp2biebbvpik8e49wlmady" UNIQUE,
                            "discount_type" varchar(255) NOT NULL,
                            "max_discount" bigint,
                            "minimum_order_amount" bigint DEFAULT 0 NOT NULL,
                            "usage_count" integer DEFAULT 0 NOT NULL,
                            "usage_limit" integer,
                            "valid_from" timestamp with time zone NOT NULL,
                            "valid_to" timestamp with time zone NOT NULL,
                            "value" bigint NOT NULL,
                            "active" boolean DEFAULT true NOT NULL,
                            CONSTRAINT "vouchers_discount_type_check" CHECK (((discount_type)::text = ANY ((ARRAY['PERCENT'::character varying, 'FIXED'::character varying])::text[]))),
	CONSTRAINT "vouchers_usage_check" CHECK (((usage_count >= 0) AND ((usage_limit IS NULL) OR (usage_count <= usage_limit)))),
	CONSTRAINT "vouchers_valid_range_check" CHECK ((valid_to > valid_from)),
	CONSTRAINT "vouchers_value_check" CHECK (((value > 0) AND (((discount_type)::text <> 'PERCENT'::text) OR (value <= 100))))
);
CREATE TABLE "wallet_transactions" (
                                       "id" bigserial PRIMARY KEY,
                                       "customer_id" bigint,
                                       "driver_id" bigint,
                                       "ride_id" bigint,
                                       "amount" bigint NOT NULL,
                                       "type" varchar(50) NOT NULL,
                                       "status" varchar(50) DEFAULT 'SUCCESS',
                                       "description" text,
                                       "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
                                       "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
                                       "wallet_type" varchar(50) NOT NULL,
                                       CONSTRAINT "chk_transaction_status" CHECK (((status)::text = ANY (ARRAY['PENDING'::text, 'SUCCESS'::text, 'FAILED'::text]))),
	CONSTRAINT "chk_transaction_type" CHECK (((type)::text = ANY ((ARRAY['DEPOSIT'::character varying, 'WITHDRAW'::character varying, 'TRIP_PAYMENT'::character varying, 'TRIP_EARNING'::character varying, 'REFUND'::character varying, 'COMMISSION_FEE'::character varying])::text[]))),
	CONSTRAINT "chk_wallet_owner" CHECK ((((customer_id IS NOT NULL) AND (driver_id IS NULL)) OR ((customer_id IS NULL) AND (driver_id IS NOT NULL)))),
	CONSTRAINT "chk_wallet_type" CHECK (((wallet_type)::text = ANY ((ARRAY['CREDIT'::character varying, 'INCOME'::character varying, 'CUSTOMER_WALLET'::character varying])::text[]))),
	CONSTRAINT "chk_wallet_type_owner" CHECK (((((wallet_type)::text = 'CUSTOMER_WALLET'::text) AND (customer_id IS NOT NULL) AND (driver_id IS NULL)) OR (((wallet_type)::text = ANY ((ARRAY['CREDIT'::character varying, 'INCOME'::character varying])::text[])) AND (driver_id IS NOT NULL) AND (customer_id IS NULL))))
);
